using Microsoft.Playwright;
namespace InsuranceAutomation.Core;
public sealed class BrowserSession : IAsyncDisposable { public IPlaywright? Playwright{get;private set;} public IBrowser? Browser{get;private set;} public IBrowserContext? Context{get;private set;} public IPage Page=>Context?.Pages.LastOrDefault()??throw new InvalidOperationException("Browser context is not started."); public string VideoDir{get;set;}="Artifacts/Videos"; public async Task StartAsync(FrameworkSettings s){Playwright=await Microsoft.Playwright.Playwright.CreateAsync();var opt=new BrowserTypeLaunchOptions{Headless=s.Headless};Browser=await Playwright.Chromium.LaunchAsync(opt);Directory.CreateDirectory(VideoDir);Context=await Browser.NewContextAsync(new(){RecordVideoDir=s.RecordVideo?VideoDir:null});Context.SetDefaultTimeout(s.TimeoutMs); if(s.Trace) await Context.Tracing.StartAsync(new(){Screenshots=true,Snapshots=true,Sources=true}); await Context.NewPageAsync();} public async Task StopAsync(string tracePath,bool trace){if(Context!=null){if(trace){Directory.CreateDirectory(Path.GetDirectoryName(tracePath)!);await Context.Tracing.StopAsync(new(){Path=tracePath});}await Context.CloseAsync();}if(Browser!=null)await Browser.CloseAsync();Playwright?.Dispose();} public async ValueTask DisposeAsync(){try{await StopAsync("Artifacts/Traces/dispose.zip",false);}catch{}} }
